/**
 * Prompt C Step 1 — Project Wiki shared contract.
 *
 * The Wiki is a set of markdown documents generated by the locked-route LLM from
 * the Context Engine profile + a bounded snapshot of the workspace, written into
 * the PROJECT-LOCAL, git-shareable directory `.tycode/wiki/`. Each document is
 * retrievable at SECTION granularity via the `@wiki` mention (section-level search).
 *
 * A plaintext `index.json` sidecar records the source snapshot (path→content hash)
 * taken at generation time, so drift is detected without re-running the model:
 * regeneration is "on demand" (user) or "on drift" (changed-files ≥ threshold).
 *
 * Nothing here imports Electron; the LLM call lives in the main service.
 */

import { z } from 'zod';

export const WIKI_INDEX_VERSION = 1 as const;

/** The fixed set of generated documents. Section ids double as file stems. */
export const WIKI_SECTIONS = [
  'overview',
  'architecture',
  'modules',
  'data-flow',
  'api-surface',
  'conventions'
] as const;

export const WikiSectionIdSchema = z.enum(WIKI_SECTIONS);
export type WikiSectionId = z.infer<typeof WikiSectionIdSchema>;

/** Workspace-relative directory holding the generated, git-shareable docs. */
export const WIKI_DIR = '.tycode/wiki';

/** Regenerate when at least this many tracked source files changed since generation. */
export const WIKI_DRIFT_FILE_THRESHOLD = 5;

export const WikiSectionMetaSchema = z.object({
  id: WikiSectionIdSchema,
  title: z.string().max(200),
  /** Path relative to the workspace root (POSIX), e.g. `.tycode/wiki/architecture.md`. */
  file: z.string().max(4096),
  generatedAt: z.number().int(),
  /** Aggregate source-snapshot hash this section was generated from. */
  sourceSnapshotHash: z.string().max(64)
});
export type WikiSectionMeta = z.infer<typeof WikiSectionMetaSchema>;

/** Plaintext sidecar at `.tycode/wiki/index.json`. */
export const WikiIndexSchema = z.object({
  v: z.literal(WIKI_INDEX_VERSION),
  wsHash: z.string().max(64),
  generatedAt: z.number().int(),
  /** Aggregate hash over the source snapshot used for the whole run. */
  sourceSnapshotHash: z.string().max(64),
  /** Per-file content hashes at generation time (for precise drift reporting). */
  fileHashes: z.record(z.string(), z.string()),
  sections: z.array(WikiSectionMetaSchema)
});
export type WikiIndex = z.infer<typeof WikiIndexSchema>;

/* --------------------------------------------------------------- IPC ------- */

export const WIKI_CHANNELS = {
  generate: 'wiki:generate',
  status: 'wiki:status',
  read: 'wiki:read',
  search: 'wiki:search',
  /** main → renderer streaming of generation progress. */
  progress: 'wiki:progress'
} as const;

export const GenerateWikiRequestSchema = z
  .object({
    workspaceRoot: z.string().min(1).max(4096),
    /** Regenerate even when not stale. */
    force: z.boolean().default(false)
  })
  .strict();
export type GenerateWikiRequest = z.infer<typeof GenerateWikiRequestSchema>;

export const WikiStatusRequestSchema = z
  .object({ workspaceRoot: z.string().min(1).max(4096) })
  .strict();
export type WikiStatusRequest = z.infer<typeof WikiStatusRequestSchema>;

export const ReadWikiSectionRequestSchema = z
  .object({
    workspaceRoot: z.string().min(1).max(4096),
    section: WikiSectionIdSchema
  })
  .strict();
export type ReadWikiSectionRequest = z.infer<typeof ReadWikiSectionRequestSchema>;

export const SearchWikiRequestSchema = z
  .object({
    workspaceRoot: z.string().min(1).max(4096),
    query: z.string().min(1).max(512),
    limit: z.number().int().positive().max(20).default(5)
  })
  .strict();
export type SearchWikiRequest = z.infer<typeof SearchWikiRequestSchema>;

export const WikiStatusSchema = z.object({
  exists: z.boolean(),
  generatedAt: z.number().int().nullable(),
  stale: z.boolean(),
  changedFiles: z.number().int().nonnegative(),
  driftThreshold: z.number().int().positive(),
  sections: z.array(WikiSectionMetaSchema)
});
export type WikiStatus = z.infer<typeof WikiStatusSchema>;

/** A section-level search hit (used by the `@wiki` mention preview too). */
export const WikiSearchHitSchema = z.object({
  section: WikiSectionIdSchema,
  title: z.string().max(200),
  score: z.number(),
  snippet: z.string().max(400)
});
export type WikiSearchHit = z.infer<typeof WikiSearchHitSchema>;

export const GenerateWikiResultSchema = z.object({
  generated: z.boolean(),
  reason: z.enum(['fresh', 'generated', 'no-stale-source', 'llm-unavailable', 'error']).optional(),
  message: z.string().max(1024).optional(),
  status: WikiStatusSchema
});
export type GenerateWikiResult = z.infer<typeof GenerateWikiResultSchema>;
